    throw new HarnessError("T1_N3_AB_PACKET_TOKEN_MISMATCH");
  }
  const workersRaw = process.env.T1_N3_AB_WORKERS;
  if (!LAWFUL_WORKER_COUNTS.includes(workersRaw)) {
