        }),
      rssSafety: {
        rssSafetyExceeded: false, limitBytes: RSS_SAFETY_LIMIT_BYTES,
        peakBytes: 390 * 1024 * 1024
      }
    }
  };
}

function syntheticFaultCell(faultName, index) {
  const base = {
