    occupiedSlots: position === 3 ? STANDALONE_SLOT_CAPACITY : (STANDALONE_SLOT_CAPACITY * position) / 4,
    sentinelExpiryEntries: position === 3
      ? STANDALONE_SENTINEL_EXPIRY_ENTRIES
