// ---------------------------------------------------------------------------

/** Exact integer binomial coefficient. Each division is exact by construction. */
function binomialCoefficient(n, k) {
  if (k < 0 || k > n) return 0n;
  const smaller = BigInt(Math.min(k, n - k));
  let result = 1n;
  const bigN = BigInt(n);
  for (let step = 0n; step < smaller; step += 1n) {
