    restartsInWindow: 0,
    rssSafety: {
      rssSafetyExceeded: false,
      limitBytes: RSS_SAFETY_LIMIT_BYTES,
      peakBytes: 120 * 1024 * 1024,
      measuredPid: 3000 + index,
      sampleIntervalMs: 5,
      samples: 40,
      peakSampleBytes: [120 * 1024 * 1024]
    },
    rssBoundStatus: REQUIRED_RSS_BOUND_LABEL,
    replacementsSpawned: 0,
