function syntheticFaultCell(faultName, index) {
  const base = {
    packetSha256: EXPECTED_PACKET_SHA256,
    header: syntheticHeader(3000 + index, 6200 + index),
    maxLiveHandles: 3,
    maxPhysicallyAlive: 3,
    settledExactlyOnce: true,
