 * matched text is never printed.
 */
const FORBIDDEN_PATTERNS = Object.freeze([
  Object.freeze({ name: "email-address", pattern: /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g }),
