      }
    }
  };
}

function syntheticArchitectureCell(workers, index, options = {}) {
  return {
    cellId: `architecture-${index}-w${workers}`,
    workers,
    rawStatus: 0,
    stdout: SELF_TEST_CLEAN_RECEIPT_STDOUT,
