+  const runResourceChild = async (
+    name: string, workers: number, retainMib: number
+  ): Promise<Record<string, unknown>> => {
+    const script = join(scratch, `${name}.mjs`);
+    await writeFile(script, resourceChildSource(workers, retainMib), "utf8");
+    // `execFile` rejects on a nonzero child, and the rejection carries the
+    // child's own stdout and code. Losing them would convert the child's exit 3
+    // into an opaque Vitest status 1 — exactly the mapping the ruled ceiling
+    // must survive — so the structured breach line is forwarded verbatim and
+    // the code is preserved before anything else is decided.
+    let stdout = "";
+    try {
+      ({ stdout } = await run(
+        process.execPath, ["--expose-gc", script], { cwd: repoRoot, maxBuffer: 64 * 1024 * 1024 }
+      ));
+    } catch (error) {
+      const failure = error as { code?: unknown; stdout?: unknown; stderr?: unknown };
+      const childStdout = typeof failure.stdout === "string" ? failure.stdout : "";
+      const breach = childStdout.split("\n")
+        .find((entry) => entry.startsWith("[T1_N3_AB_RSS_SAFETY_EXCEEDED]"));
+      if (breach !== undefined) process.stdout.write(`${breach}\n`);
+      expect(failure.code, "T1_N3_AB_CHILD_EXIT_CODE_PRESERVED").toBeDefined();
+      expect(breach === undefined, "T1_N3_AB_RSS_SAFETY_EXCEEDED").toBe(true);
